input.command:
head -n -2 tests/rotate_test.sh > /tmp/t && cat >> /tmp/t <<'EOF'
for i in 3 4 5 6; do echo "n$i" > "$d/logs/app.log"; bash bin/rotate "$d/logs" "$d/archive" app.log 2026100$i; done
[ "$(ls "$d/logs" | grep -c '^app.log.[0-9]')" = 3 ] || { echo "local keep"; fail=1; }
[ ! -e "$d/logs/app.log.4" ] || { echo "local old"; fail=1; }
[ "$(ls "$d/archive")" = "$(printf 'app.log.20261004\napp.log.20261005\napp.log.20261006')" ] || { echo "archive keep"; fail=1; }
rm -rf "$d"
exit $fail
EOF
cp /tmp/t tests/rotate_test.sh; tail -9 tests/rotate_test.sh | head -3; bash scripts/verify.sh && echo PASS
